	@Test
	void nativeConditioningUsesTheSameMappedPrefixAndDeclinesUnknownDistinctEvidence() throws Exception {
		for (double distinct : List.of(4.0d, Double.NaN)) {
			Fixture fixture = new Fixture(0.0d, 404.0d, true);
			fixture.distinct = distinct;
			StatementPattern prefix = new StatementPattern(Var.of("anchor"), Var.of("q", Q), Var.of("p"));
			StatementPattern repeated = new StatementPattern(Var.of("x"), Var.of("p"), Var.of("x"));
			PackedCostEstimate output = fixture.append(prefix, repeated);
			assertEquals(0.0d, output.outputRows());
			if (Double.isFinite(distinct)) {
				assertEquals(101.0d, output.accessRows());
				assertEquals(707.0d, output.sequentialRows(), 0.0d, "the prefix has seven rows");
			} else {
				assertTrue(Double.isNaN(output.accessRows()));
				assertTrue(Double.isNaN(output.workRows()));
				assertFalse(output.hasExplicitPhysicalCost());
				assertTrue(Double.isNaN(output.plannedDoubleMetric("plannedCostSequentialRows", Double.NaN)));
			}
			fixture.assertNoMappedSnapshotFallback();
		}
	}

