		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s", Q), Var.of("p", P), Var.of("same"), Var.of("same"));
		PackedCostEstimate output = fixture.leaf(pattern);
